-- The 7 commissary checklists reduce to 5 templates: Angel's Pizza and
-- Angel's Pizza Consolacion's source files are byte-identical (confirmed
-- by direct diff), so one shared template covers both facilities, same as
-- the Mayon/Consolacion/CDO warehouse checklists. The other 5 (Figaro,
-- Tien Ma's, ISD, Roasting, Tarlac) each have genuinely distinct content.
--
-- All QA-only (requires_audit_type), point-weighted (1/5pt as given),
-- Commitment Date enabled, pass threshold 92.5% per standing rule
-- (sources vary — some say 93%, Figaro's says 90% — disregarded either
-- way). Section numbering is kept as each source file had it (some use
-- lettered A/B/C, some use lowercase roman numerals i/ii/iii, and a few
-- have leftover "xiv"/"xv" numbering on their last two sections from
-- being copy-pasted across files) — cosmetic only, doesn't affect scoring.


INSERT INTO public.audit_templates (
  id, title, description, sections, is_active, template_group, active_ticket,
  pass_threshold, requires_audit_type, requires_visit_number, requires_commitment_date,
  requires_department, has_time_restriction, available_from_time, available_to_time,
  store_restrictions, created_date, updated_date
)
