  true, 'others', false,
  92.5, true, false, true,
  false, false, '', '',
  (
    SELECT jsonb_agg(jsonb_build_object('brand_id', b.id, 'brand_name', b.brand_name, 'store_id', s.id, 'store_name', s.store_name))
    FROM public.stores s
    JOIN public.brands b ON b.id = s.brand_id
    WHERE s.store_name IN (('Angel''s Pizza Commissary'), ('Angel''s Pizza Consolacion Commissary'))
  ),
  now(), now()
WHERE NOT EXISTS (
  SELECT 1 FROM public.audit_templates WHERE title = 'Angel''s Pizza Commissary Facility Audit Checklist'
);


